<script setup lang="ts">
import {ref,onMounted} from 'vue';
import {useRoute} from 'vue-router';
import type {TemplateSummary,Page} from '@survey/shared';
import {api} from '../api';
import {queryPage} from '../library-client';
const route=useRoute(),scope=ref(route.query.scope==='mine'?'mine':'square'),rows=ref<TemplateSummary[]>([]),cursor=ref<string|null>(null),busy=ref(false),error=ref(''),notice=ref('');
async function load(more=false){busy.value=true;error.value='';try{const p=await api<Page<TemplateSummary>>('/templates'+queryPage({scope:scope.value,limit:'20',cursor:more?cursor.value??undefined:undefined}));rows.value=more?[...rows.value,...p.items]:p.items;cursor.value=p.nextCursor;}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function state(t:TemplateSummary){busy.value=true;error.value='';try{await api(`/templates/${t.id}/${t.status==='listed'?'unlisting':'listing'}`,'POST',{expectedRevision:t.revision});notice.value=t.status==='listed'?'模板已下架，已生成问卷不受影响。':'模板已重新上架。';await load();}catch(e){error.value=`${(e as Error).message}。结果未知时先刷新比较当前状态。`;}finally{busy.value=false;}}
onMounted(()=>load());
</script>
<template><section class="narrow"><h1 tabindex="-1">模板广场</h1><p class="muted">选用固定问卷结构，生成自己的新草稿。这里不公开他人答卷或统计；私人共享不等于公开分发授权。</p><div class="editor-actions"><button class="secondary" :aria-pressed="scope==='square'" :disabled="busy" @click="scope='square';load()">可选用模板</button><button class="secondary" :aria-pressed="scope==='mine'" :disabled="busy" @click="scope='mine';load()">我的模板</button></div><p v-if="error" class="error" role="alert">{{error}} <button class="quiet" @click="load()">刷新模板列表</button></p><p v-if="notice" class="saved" role="status">{{notice}}</p><p v-if="busy" role="status" aria-busy="true">正在核对模板及当前公开授权…</p><p v-if="!busy&&!rows.length&&!error" class="panel">{{cursor?'本页没有当前可用模板，可以继续加载后续模板。':scope==='mine'?'还没有发布模板。在本人问卷发布页选择明确发布版后创建。':'目前没有可选用模板。'}}</p><ul class="survey-list"><li v-for="t in rows" :key="t.id" class="panel"><h2><RouterLink :to="`/templates/${t.id}`">{{t.title}}</RouterLink></h2><p>{{t.description}}</p><p class="muted">{{t.status==='listed'?'已上架':'已下架'}} · {{t.eligible?'当前来源授权有效':'当前不可公开选用，需核对具体版本与上游授权'}}</p><div class="editor-actions"><RouterLink :to="`/templates/${t.id}`">查看固定模板 →</RouterLink><button v-if="scope==='mine'" class="quiet" :disabled="busy" @click="state(t)">{{t.status==='listed'?'下架此模板':'重新上架此模板'}}</button></div></li></ul><button v-if="cursor" class="secondary more" :disabled="busy" @click="load(true)">继续加载模板</button></section></template>
